CREATE TABLE IF NOT EXISTS model_trial_accounts (user_id INTEGER PRIMARY KEY,limit_turns INTEGER NOT NULL DEFAULT 5,granted_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS model_trial_turns (user_id INTEGER NOT NULL,message_id TEXT NOT NULL,fingerprint TEXT NOT NULL,created_at INTEGER NOT NULL,PRIMARY KEY(user_id,message_id));
CREATE TABLE IF NOT EXISTS model_trial_migrations (id TEXT PRIMARY KEY,initialized_at INTEGER NOT NULL);
CREATE TRIGGER IF NOT EXISTS model_trial_new_user AFTER INSERT ON users BEGIN INSERT OR IGNORE INTO model_trial_accounts(user_id,limit_turns,granted_at) VALUES(NEW.id,5,CAST(strftime('%s','now') AS INTEGER)*1000); END;
CREATE TRIGGER IF NOT EXISTS model_trial_limit BEFORE INSERT ON model_trial_turns BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM model_trial_turns WHERE user_id=NEW.user_id AND message_id=NEW.message_id AND fingerprint<>NEW.fingerprint) THEN RAISE(ABORT,'MODEL_TRIAL_ID_REUSED') END; SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM model_trial_turns WHERE user_id=NEW.user_id AND message_id=NEW.message_id) AND (SELECT COUNT(*) FROM model_trial_turns WHERE user_id=NEW.user_id)>=COALESCE((SELECT limit_turns FROM model_trial_accounts WHERE user_id=NEW.user_id),0) THEN RAISE(ABORT,'MODEL_TRIAL_EXHAUSTED') END; END;
INSERT OR IGNORE INTO model_trial_accounts(user_id,limit_turns,granted_at) SELECT id,5,CAST(strftime('%s','now') AS INTEGER)*1000 FROM users WHERE NOT EXISTS(SELECT 1 FROM model_trial_migrations WHERE id='deepseek-five-turns-v1') AND NOT EXISTS(SELECT 1 FROM user_subscription WHERE user_id=users.id AND expires_at>CAST(strftime('%s','now') AS INTEGER)*1000);
INSERT OR IGNORE INTO model_trial_migrations(id,initialized_at) VALUES('deepseek-five-turns-v1',CAST(strftime('%s','now') AS INTEGER)*1000);
